def edit(cid,fid,statement=None,refs=None):
 e=rows[cid];f=next(f for f in e['required_facts'] if f['id']==fid)
 if statement is not None:f['statement']=statement
 if refs is not None:f['source_refs']=refs
def add(cid,statement,refs):
 e=rows[cid];n=max(int(f['id'][1:]) for key in ['required_facts','optional_enrichment'] for f in e[key])+1
 e['required_facts'].append(dict(id=f'f{n}',statement=statement,source_refs=refs))
