edit('mle.prediction_authentication','f10','For the supplied Google ID-token verifier contract, import from google.oauth2 import id_token and from google.auth.transport import requests (as Python statements: from google.oauth2 import id_token; from google.auth.transport import requests); implement def authorize_prediction(token, expected_audience, permitted_subjects): to reject a missing token, call claims = id_token.verify_oauth2_token(token, requests.Request(), audience=expected_audience), and admit only claims["sub"] in the supplied permitted_subjects policy; use the verified sub identity, not an unverified decode or a changeable email address.',[authref,verref])
